#include <array>
#include <cstddef>
#include <iostream>

int main() {
    std::array<int, 3> datos{2, 5, 8};
    int cantidad = 0;
    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 10) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int indice = 0;
        int cambio = 0;
        if (!(std::cin >> indice >> cambio)) {
            return 1;
        }
        if (indice < 0 || indice > 2) {
            std::cout << "Indice invalido;Antes:-1;Actual:-1";
        } else {
            int& seleccionado = datos[static_cast<std::size_t>(indice)];
            const int antes = seleccionado;
            bool aceptada = false;
            if (cambio >= -3 && cambio <= 3) {
                const int candidato = seleccionado + cambio;
                if (candidato >= 0 && candidato <= 9) {
                    seleccionado = candidato;
                    aceptada = true;
                }
            }
            std::cout << (aceptada ? "Aceptada" : "Rechazo")
                      << ";Antes:" << antes << ";Actual:" << seleccionado;
        }
        std::cout << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << '\n';
    }
    return 0;
}
